import{_ as p,a0 as l,w as o,s as c,ao as d,I as a,x as i,a1 as n,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"在 RHEL8 配置靜態 IP 地址的不同方法 | LCTT x X-CMD","titleTemplate":false,"description":"在 RHEL8 配置靜態 IP 地址的不同方法 | LCTT (201909) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 RHEL8 配置靜態 IP 地址的不同方法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 RHEL8 配置靜態 IP 地址的不同方法 | LCTT (201909) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201909/20190901 Different Ways to Configure Static IP Address in RHEL 8","title":"在 RHEL8 配置靜態 IP 地址的不同方法","tag":"201909","desc":""},"relativePath":"201909/20190901 Different Ways to Configure Static IP Address in RHEL 8.md","filePath":"[post].md"}'),r={name:"201909/20190901 Different Ways to Configure Static IP Address in RHEL 8.md"};function h(u,s,g,f,k,b){const e=l("Link");return o(),c("div",null,[s[15]||(s[15]=d(`<h1 id="在-rhel8-配置靜態-ip-地址的不同方法" tabindex="-1">在 RHEL8 配置靜態 IP 地址的不同方法 <a class="header-anchor" href="#在-rhel8-配置靜態-ip-地址的不同方法" aria-label="Permalink to “在 RHEL8 配置靜態 IP 地址的不同方法”">​</a></h1><p>在 Linux 服務器上工作時，在網卡/以太網卡上分配靜態 IP 地址是每個 Linux 工程師的常見任務之一。如果一個人在 Linux 服務器上正確配置了靜態地址，那麼他/她就可以通過網絡遠程訪問它。在本文中，我們將演示在 RHEL 8 服務器網卡上配置靜態 IP 地址的不同方法。</p><p><img src="https://img.linux.net.cn/data/attachment/album/201909/25/222737dx94bbl9qbhzlfe4.jpg" alt=""></p><p>以下是在網卡上配置靜態IP的方法：</p><ul><li><code>nmcli</code>（命令列工具）</li><li>網絡腳本文件（<code>ifcfg-*</code>）</li><li><code>nmtui</code>（基於文本的用户界面）</li></ul><h3 id="使用-nmcli-命令列工具配置靜態-ip-地址" tabindex="-1">使用 nmcli 命令列工具配置靜態 IP 地址 <a class="header-anchor" href="#使用-nmcli-命令列工具配置靜態-ip-地址" aria-label="Permalink to “使用 nmcli 命令列工具配置靜態 IP 地址”">​</a></h3><p>每當我們安裝 RHEL 8 服務器時，就會自動安裝命令列工具 <code>nmcli</code>，它是由網絡管理器使用的，可以讓我們在以太網卡上配置靜態 IP 地址。</p><p>運行下面的 <code>ip addr</code> 命令，列出 RHEL 8 服務器上的以太網卡</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# ip addr</span></span></code></pre></div><p>正如我們在上面的命令輸出中看到的，我們有兩個網卡 <code>enp0s3</code> 和 <code>enp0s8</code>。當前分配給網卡的 IP 地址是通過 DHCP 服務器獲得的。</p><p>假設我們希望在第一個網卡 (<code>enp0s3</code>) 上分配靜態 IP 地址，具體內容如下:</p><ul><li>IP 地址 = 192.168.1.4</li><li>網絡掩碼 = 255.255.255.0</li><li>網關 = 192.168.1.1</li><li>DNS = 8.8.8.8</li></ul><p>依次運行以下 <code>nmcli</code> 命令來配置靜態 IP，</p><p>使用 <code>nmcli connection</code> 命令列出當前活動的以太網卡，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# nmcli connection</span></span>
<span class="line"><span>NAME    UUID                                  TYPE      DEVICE</span></span>
<span class="line"><span>enp0s3  7c1b8444-cb65-440d-9bf6-ea0ad5e60bae  ethernet  enp0s3</span></span>
<span class="line"><span>virbr0  3020c41f-6b21-4d80-a1a6-7c1bd5867e6c  bridge    virbr0</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><p>使用下面的 <code>nmcli</code> 給 <code>enp0s3</code> 分配靜態 IP。</p><p><strong>命令語法：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># nmcli connection modify &lt;interface_name&gt; ipv4.address  &lt;ip/prefix&gt;</span></span></code></pre></div><p><strong>注意:</strong> 為了簡化語句，在 <code>nmcli</code> 命令中，我們通常用 <code>con</code> 關鍵字替換 <code>connection</code>，並用 <code>mod</code> 關鍵字替換 <code>modify</code>。</p><p>將 IPv4 地址 (192.168.1.4) 分配給 <code>enp0s3</code> 網卡上，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# nmcli con mod enp0s3 ipv4.addresses 192.168.1.4/24</span></span></code></pre></div><p>使用下面的 <code>nmcli</code> 命令設置網關，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# nmcli con mod enp0s3 ipv4.gateway 192.168.1.1</span></span></code></pre></div><p>設置手動配置（從 dhcp 到 static），</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# nmcli con mod enp0s3 ipv4.method manual</span></span></code></pre></div><p>設置 DNS 值為 “8.8.8.8”，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# nmcli con mod enp0s3 ipv4.dns &quot;8.8.8.8&quot;</span></span></code></pre></div><p>要保存上述更改並重新加載，請執行如下 <code>nmcli</code> 命令，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# nmcli con up enp0s3</span></span>
<span class="line"><span>Connection successfully activated (D-Bus active path: /org/freedesktop/NetworkManager/ActiveConnection/4)</span></span></code></pre></div><p>以上命令顯示網卡 <code>enp0s3</code> 已成功配置。我們使用 <code>nmcli</code> 命令做的那些更改都將永久保存在文件 <code>etc/sysconfig/network-scripts/ifcfg-enp0s3</code> 裏。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# cat /etc/sysconfig/network-scripts/ifcfg-enp0s3</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/ifcfg-enp0s3-file-rhel8.jpg" alt="ifcfg-enp0s3-file-rhel8"></p><p>要確認 IP 地址是否分配給了 <code>enp0s3</code> 網卡了，請使用以下 IP 命令查看，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]#ip addr show enp0s3</span></span></code></pre></div><h3 id="使用網絡腳本文件-ifcfg-手動配置靜態-ip-地址" tabindex="-1">使用網絡腳本文件（ifcfg-*）手動配置靜態 IP 地址 <a class="header-anchor" href="#使用網絡腳本文件-ifcfg-手動配置靜態-ip-地址" aria-label="Permalink to “使用網絡腳本文件（ifcfg-*）手動配置靜態 IP 地址”">​</a></h3><p>我們可以使用配置以太網卡的網絡腳本或 <code>ifcfg-*</code> 文件來配置以太網卡的靜態 IP 地址。假設我們想在第二個以太網卡 <code>enp0s8</code> 上分配靜態 IP 地址：</p><ul><li>IP 地址 = 192.168.1.91</li><li>前綴 = 24</li><li>網關 =192.168.1.1</li><li>DNS1 =4.2.2.2</li></ul><p>轉到目錄 <code>/etc/sysconfig/network-scripts</code>，查找文件 <code>ifcfg-enp0s8</code>，如果它不存在，則使用以下內容創建它，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# cd /etc/sysconfig/network-scripts/</span></span>
<span class="line"><span>[root@linuxtechi network-scripts]# vi ifcfg-enp0s8</span></span>
<span class="line"><span>TYPE=&quot;Ethernet&quot;</span></span>
<span class="line"><span>DEVICE=&quot;enp0s8&quot;</span></span>
<span class="line"><span>BOOTPROTO=&quot;static&quot;</span></span>
<span class="line"><span>ONBOOT=&quot;yes&quot;</span></span>
<span class="line"><span>NAME=&quot;enp0s8&quot;</span></span>
<span class="line"><span>IPADDR=&quot;192.168.1.91&quot;</span></span>
<span class="line"><span>PREFIX=&quot;24&quot;</span></span>
<span class="line"><span>GATEWAY=&quot;192.168.1.1&quot;</span></span>
<span class="line"><span>DNS1=&quot;4.2.2.2&quot;</span></span></code></pre></div><p>保存並退出文件，然後重新啓動網絡管理器服務以使上述更改生效，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi network-scripts]# systemctl restart NetworkManager</span></span></code></pre></div><p>現在使用下面的 <code>ip</code> 命令來驗證 IP 地址是否分配給網卡，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# ip add show enp0s8</span></span>
<span class="line"><span>3: enp0s8: &lt;BROADCAST,MULTICAST,UP,LOWER_UP&gt; mtu 1500 qdisc fq_codel state UP group default qlen 1000</span></span>
<span class="line"><span>    link/ether 08:00:27:7c:bb:cb brd ff:ff:ff:ff:ff:ff</span></span>
<span class="line"><span>    inet 192.168.1.91/24 brd 192.168.1.255 scope global noprefixroute enp0s8</span></span>
<span class="line"><span>       valid_lft forever preferred_lft forever</span></span>
<span class="line"><span>    inet6 fe80::a00:27ff:fe7c:bbcb/64 scope link</span></span>
<span class="line"><span>       valid_lft forever preferred_lft forever</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><p>以上輸出內容確認靜態 IP 地址已在網卡 <code>enp0s8</code> 上成功配置了。</p><h3 id="使用-nmtui-實用程序配置靜態-ip-地址" tabindex="-1">使用 nmtui 實用程序配置靜態 IP 地址 <a class="header-anchor" href="#使用-nmtui-實用程序配置靜態-ip-地址" aria-label="Permalink to “使用 nmtui 實用程序配置靜態 IP 地址”">​</a></h3><p><code>nmtui</code> 是一個基於文本用户界面的，用於控制網絡的管理器，當我們執行 <code>nmtui</code> 時，它將打開一個基於文本的用户界面，通過它我們可以添加、修改和刪除連接。除此之外，<code>nmtui</code> 還可以用來設置系統的主機名。</p><p>假設我們希望通過以下細節將靜態 IP 地址分配給網卡 <code>enp0s3</code> ，</p><ul><li>IP 地址 = 10.20.0.72</li><li>前綴 = 24</li><li>網關 = 10.20.0.1</li><li>DNS1 = 4.2.2.2</li></ul><p>運行 <code>nmtui</code> 並按照屏幕説明操作，示例如下所示，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# nmtui</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/nmtui-rhel8.jpg" alt="nmtui-rhel8"></p><p>選擇第一個選項 “Edit a connection”，然後選擇接口為 “enp0s3”，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Choose-interface-nmtui-rhel8.jpg" alt="Choose-interface-nmtui-rhel8"></p><p>選擇 “Edit”，然後指定 IP 地址、前綴、網關和域名系統服務器 IP，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/set-ip-nmtui-rhel8.jpg" alt="set-ip-nmtui-rhel8"></p><p>選擇確定，然後點擊回車。在下一個窗口中，選擇 “Activate a connection”，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Activate-option-nmtui-rhel8.jpg" alt="Activate-option-nmtui-rhel8"></p><p>選擇 “enp0s3”，選擇 “Deactivate” 並點擊回車，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Deactivate-interface-nmtui-rhel8.jpg" alt="Deactivate-interface-nmtui-rhel8"></p><p>現在選擇 “Activate” 並點擊回車，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Activate-interface-nmtui-rhel8.jpg" alt="Activate-interface-nmtui-rhel8"></p><p>選擇 “Back”，然後選擇 “Quit”，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Quit-Option-nmtui-rhel8.jpg" alt="Quit-Option-nmtui-rhel8"></p><p>使用下面的 <code>ip</code> 命令驗證 IP 地址是否已分配給接口 <code>enp0s3</code>，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# ip add show enp0s3</span></span>
<span class="line"><span>2: enp0s3: &lt;BROADCAST,MULTICAST,UP,LOWER_UP&gt; mtu 1500 qdisc fq_codel state UP group default qlen 1000</span></span>
<span class="line"><span>    link/ether 08:00:27:53:39:4d brd ff:ff:ff:ff:ff:ff</span></span>
<span class="line"><span>    inet 10.20.0.72/24 brd 10.20.0.255 scope global noprefixroute enp0s3</span></span>
<span class="line"><span>       valid_lft forever preferred_lft forever</span></span>
<span class="line"><span>    inet6 fe80::421d:5abf:58bd:c47e/64 scope link noprefixroute</span></span>
<span class="line"><span>       valid_lft forever preferred_lft forever</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><p>以上輸出內容顯示我們已經使用 <code>nmtui</code> 實用程序成功地將靜態 IP 地址分配給接口 <code>enp0s3</code>。</p><p>以上就是本教程的全部內容，我們已經介紹了在 RHEL 8 系統上為以太網卡配置 IPv4 地址的三種不同方法。請在下面的評論部分分享反饋和評論。</p><hr>`,68)),a("p",null,[s[1]||(s[1]=i("via: ",-1)),n(e,{href:"https://www.linuxtechi.com/configure-static-ip-address-rhel8/"},{default:t(()=>[...s[0]||(s[0]=[i("https://www.linuxtechi.com/configure-static-ip-address-rhel8/",-1)])]),_:1})]),a("p",null,[s[6]||(s[6]=i("作者：",-1)),n(e,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:t(()=>[...s[2]||(s[2]=[i("Pradeep Kumar",-1)])]),_:1}),s[7]||(s[7]=i(" 選題：",-1)),n(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[3]||(s[3]=[i("lujun9972",-1)])]),_:1}),s[8]||(s[8]=i(" 譯者：",-1)),n(e,{href:"https://github.com/heguangzhi"},{default:t(()=>[...s[4]||(s[4]=[i("heguangzhi",-1)])]),_:1}),s[9]||(s[9]=i(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[5]||(s[5]=[i("wxy",-1)])]),_:1})]),a("p",null,[s[12]||(s[12]=i("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[10]||(s[10]=[i("LCTT",-1)])]),_:1}),s[13]||(s[13]=i(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:t(()=>[...s[11]||(s[11]=[i("Linux中國",-1)])]),_:1}),s[14]||(s[14]=i(" 榮譽推出",-1))])])}const P=p(r,[["render",h]]);export{v as __pageData,P as default};
